  async function search(q) { if (!st.data) { try { st.data = await SUITE.db.load("notes", DEF); } catch (e) { return []; } } q = q.toLowerCase(); return allPages().filter((p) => live(p) && ((p.title || "").toLowerCase().includes(q) || plain(p).toLowerCase().includes(q))).slice(0, 8).map((p) => ({ l: p.title || "Untitled", d: typeOf(p.type).name + " · " + SUITE.ago(p.updatedAt), fn: () => SUITE.open("notes", { page: p.id }) })); }
