  SUITE.register("notes", { sharedByMe, mount, unmount, refresh, onEsc, onBack, onKey, summary, help, reminders, exportData, importData, search, shareCurrent, defaults: DEF, open(opt) { if (opt && opt.page) openPage(opt.page); }, onLock: () => { if (st.rec && st.rec.state !== "inactive") st.rec.stop(); } });
